"""Live specified-source acceptance on balanced clustering and real network bisection.
Model and adapter generated by local LLM; dataset-specific independent checks precede solving.
"""
import argparse,json,os,sys,time
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from dotenv import load_dotenv
load_dotenv(ROOT/'.env')
from qubo_auto.llm_client import LLMClient
from qubo_auto.annealing import modeler
from qubo_auto.annealing.acquisition import prepare_real_data
from qubo_auto.annealing.artifacts import ArtifactStore,atomic_write
from qubo_auto.annealing.datakit import load_tables
from qubo_auto.annealing.backends import get_backend
from qubo_auto.annealing.baselines import make_policy
from qubo_auto.annealing.workflow import run_workflow


def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--case',choices=['karate','wholesale'],required=True);p.add_argument('--out',type=Path,required=True);p.add_argument('--model-file',type=Path);a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True)
 os.environ['LLM_ENABLE_THINKING']='false'
 if a.case=='karate':
  source='https://websites.umich.edu/~mejn/netdata/'
  spec={'problem_summary':'Download Zachary karate club graph from the specified university source; use all 34 nodes and unweighted edges. Partition into two groups of exactly 17 nodes, minimizing cut edges. SOURCE PAGE: '+source+' SOURCE FILE: https://websites.umich.edu/~mejn/netdata/karate.zip',
   'constraints':[{'name':'balance','strength':'hard','description':'Exactly half of all nodes in each group'}],
   'objectives':[{'name':'cut','direction':'minimize','description':'sum_{i<j} adjacency[i,j]*(x_i-x_j)^2'}],
   'assumptions':['Required DATA_SCHEMA keys: adjacency (square binary matrix), k (size of group one). GML loader provides node_id and adj_0...adj_33 columns. Retain all rows, ignore node_id in adjacency. k=17 for real data. Synthetic make_example_data uses even size and k=size//2 so small tests stay feasible. REQUIREMENT_MAP balance must point to actual IR constraint names. This is equal-size bisection, not reproducing the historical split.']}
 else:
  source='https://archive.ics.uci.edu/dataset/292/wholesale+customers'
  spec={'problem_summary':'Download real Wholesale Customers CSV. Select exactly 24 original rows with pandas random_state=0, then log1p-transform and population-standardize (ddof=0) each of Fresh, Milk, Grocery, Frozen, Detergents_Paper, Delicassen on those 24 rows. Divide into 3 groups of exactly 8, minimizing within-group sum of pairwise squared Euclidean distances. SOURCE PAGE: '+source,
   'constraints':[{'name':'one_group','strength':'hard','description':'Every customer belongs to exactly one group'},{'name':'group_size','strength':'hard','description':'Each of three groups has exactly eight members'}],
   'objectives':[{'name':'within_distance','direction':'minimize','description':'sum_{i<j,g} distances[i,j]*x[i,g]*x[j,g]'}],
   'assumptions':['Required DATA_SCHEMA keys: ids (original zero-based row indices), distances (24x24 squared distances), groups=3, group_size=8. Use prep.sample_rows(df,24,seed=0,log=log); include original index in ids, do not reset before retaining IDs. Retain sample order. Standardize after sampling, ddof=0. Zero standard deviation is an error, not a made-up substitute. Explicit variable order i*groups+g. Synthetic examples use size divisible by 3 and group_size=size//3. Correlation/standardized distances dimensionless; spending measured in original monetary units, not TWD. Contracts on distances, ids are public-derived, groups/group_size user settings. REQUIREMENT_MAP uses actual returned constraint names.']}
 spec_text=json.dumps(spec,ensure_ascii=False);atomic_write(a.out/'confirmed_spec.json',spec_text)
 client=LLMClient(a.out/'transcripts','live',max_tokens=120000,use_cache=False);client.client=client.client.with_options(timeout=180,max_retries=0)
 start=time.time();report={'case':a.case,'success':False,'source_mode':'specified primary publisher','model_origin':'live local LLM','adapter_origin':'live local LLM'}
 if (a.out/'acceptance.json').exists():atomic_write(a.out/f'acceptance_previous_{time.time_ns()}.json',(a.out/'acceptance.json').read_text())
 try:
  if a.model_file:
   code=a.model_file.read_text();ns=modeler.load_module(code);errors,validation=modeler.validate(ns);report['model_origin']='reused generated model, revalidated'
  else:
   code,ns,errors,validation=modeler.build_model(spec_text,'[]',client,os.environ.get('LLM_MODEL','qwen3.6-35b-a3b'),max_attempts=3,backend='local SA')
  atomic_write(a.out/'model.py',code)
  if errors:raise ValueError('model: '+'; '.join(errors))
  store=ArtifactStore(a.out/'artifacts')
  notes='Apply the exact confirmed transformations and schema. ADAPTER_METADATA must declare each field. assumptions=[] for operations already confirmed. Use only the specified dataset.'
  if a.case=='karate':
   notes += ' Adjacency columns MUST use numeric suffix order adj_0,adj_1,...,adj_33, never lexicographic sorting. Check matrix symmetry. Prior adapter used sorted(strings) and permuted columns without rows; independent source audit rejected it.'
  data,errors,prep=prepare_real_data(code,spec_text,client,os.environ.get('LLM_MODEL','qwen3.6-35b-a3b'),store.root/'data_files',search_rounds=2,max_downloads=2,notes=notes,log=lambda s:print(s,flush=True))
  report['preprocessing']=prep
  reviews=prep.get('review_required',[])
  known_notes={"Rows in the input table are assumed to correspond to nodes 0..33 in order, ignoring the 'node_id' column values.","The adjacency matrix is symmetric; any asymmetry in the source data (if present) would be an error, but we trust the source.","k is fixed at 17 (half of 34 nodes) as per the problem specification for equal-size bisection."}
  allowed_reviews=set()
  if a.case=='karate':
   for key,info in prep.get('data_metadata',{}).items():
    notes=info.get('assumptions') or []
    if isinstance(notes,str):notes=[notes]
    if notes and all(note in known_notes for note in notes):allowed_reviews.add(f"{key}: {info['assumptions']}")
  if errors or any(note not in allowed_reviews for note in reviews):raise ValueError('data: '+'; '.join(errors+reviews))
  report['case_specific_review_notes']=reviews
  tables={}
  for file in (store.root/'data_files').iterdir():
   if not file.name.startswith('_'):
    try:tables.update(load_tables([file]))
    except Exception:continue
  ir=modeler.to_ir(ns['build_ir'](data),'live_'+a.case)
  rng=np.random.default_rng(0)
  if a.case=='karate':
   original=next(df for df in tables.values() if 'adj_0' in df.columns);expected=original[[f'adj_{i}' for i in range(len(original))]].to_numpy()
   if expected.shape!=(34,34) or np.sum(expected)!=156 or not np.array_equal(data['adjacency'],expected) or data.get('k',17)!=17 or ir.n_variables!=34:raise ValueError('independent check: original 34-node/78-edge graph mismatch')
   probes=[rng.integers(0,2,34).tolist() for _ in range(256)]
   # Include explicitly balanced assignments (one fixed selection per probe).
   for _ in range(32):
    chosen=set(rng.choice(34,17,replace=False));probes.append([int(i in chosen) for i in range(34)])
   def objective(x):return float(sum(expected[i,j]*(x[i]-x[j])**2 for i in range(34) for j in range(i+1,34)))
   def feasible(x):return sum(x)==17
   report['original_size']={'nodes':34,'edges':78}
  else:
   original=next(df for df in tables.values() if 'Fresh' in df.columns);sample=original.sample(n=24,random_state=0);cols=['Fresh','Milk','Grocery','Frozen','Detergents_Paper','Delicassen'];z=np.log1p(sample[cols].to_numpy());z=(z-z.mean(axis=0))/z.std(axis=0,ddof=0);expected=((z[:,None,:]-z[None,:,:])**2).sum(axis=2)
   if data['ids']!=sample.index.tolist() or not np.allclose(data['distances'],expected) or data.get('groups',3)!=3 or data.get('group_size',8)!=8 or ir.n_variables!=72:raise ValueError('independent check: fixed sample, transforms, dimensions or group settings mismatch')
   probes=[rng.integers(0,2,72).tolist() for _ in range(128)]
   for _ in range(32):
    assignment=np.repeat(np.arange(3),8);rng.shuffle(assignment);probes.append(np.eye(3,dtype=int)[assignment].ravel().tolist())
   def objective(x):
    groups=np.array(x).reshape(24,3);return sum(expected[i,j]*np.dot(groups[i],groups[j]) for i in range(24) for j in range(i+1,24))
   def feasible(x):
    groups=np.array(x).reshape(24,3);return bool(np.all(groups.sum(axis=1)==1) and np.all(groups.sum(axis=0)==8))
   report['original_size']={'rows':len(original),'selected_rows':24,'spending_features':6}
  sign=1 if ir.sense=='minimize' else -1
  for bits in probes:
   if not np.isclose(sign*ir.objective(bits),objective(bits)) or all(c.satisfied(bits) for c in ir.constraints)!=feasible(bits):raise ValueError('independent check: generated objective/constraints differ from confirmed problem')
  report['independent_checks']=len(probes)
  store.commit(code,data,'independently checked real data',{'source':'real','report':prep,'confirmed_spec':spec,'data_review_approved':bool(reviews)})
  cfg={'loop':{'max_solver_calls':4,'patience':4},'workflow':{'max_repairs':0},'penalty_search':{'compiler':'pyqubo'},'param_caps':{'sa':{'num_reads':80,'num_sweeps':500}}}
  result=run_workflow(store,get_backend('sa'),lambda:make_policy('penalty_tpe'),cfg,log=lambda s:print(s,flush=True));report['workflow']=result;x=result['solution'];report['success']=x is not None and feasible(x);report['requested_objective']=objective(x) if x is not None else None
  report['description']=modeler.to_jsonable(ns['describe_solution'](data,x)) if x is not None else None
  atomic_write(a.out/'delivery.md','# '+a.case+' 真實資料成果\n\n'+json.dumps({k:report[k] for k in ['success','requested_objective','original_size','description']},ensure_ascii=False,indent=2)+'\n')
 except Exception as e:report['error']=f'{type(e).__name__}: {e}'
 report.update(wall_s=time.time()-start,llm_tokens=client.tokens_used);atomic_write(a.out/'acceptance.json',json.dumps(report,ensure_ascii=False,indent=2,default=str));print(json.dumps({k:report.get(k) for k in ['case','success','error','wall_s','llm_tokens','requested_objective']},ensure_ascii=False),flush=True)
 if not report['success']:sys.exit(1)
if __name__=='__main__':main()
